import { OpenWorldData } from '../world/openworld/OpenWorldTypes';
import { SuwonDistrictId, SuwonMapDataset } from './suwonTypes';
import worldJson from './openworld/suwonWorld.json';

/** Always-loaded unified Suwon open world (generated by `npm run map:build`, © OpenStreetMap contributors) */
export const SUWON_OPEN_WORLD = worldJson as unknown as OpenWorldData;

/**
 * Builds the single game dataset for the unified Suwon open world:
 * - road graph, signals and bus stops cover the whole 6.2km x 4.25km city
 * - every district's hand-tuned shops / residences / gas stations / repair shops are included (world coordinates)
 * - plus shops & residences generated from OSM across the whole map, so calls exist between the districts too
 * - buildings, parks, waters and pedestrian streets are empty here: they stream in per 200m chunk (ChunkStreamer)
 * - spawn, station and the primary service spots come from the chosen spawn district
 */
export function buildUnifiedSuwonDataset(spawnDistrictId: SuwonDistrictId): SuwonMapDataset {
  const w = SUWON_OPEN_WORLD;
  const districts = w.legacyDistricts;
  const spawn = districts.find((d) => d.id === spawnDistrictId) ?? districts[0];
  const b = w.meta.bounds;
  return {
    meta: {
      id: spawn.id as SuwonDistrictId,
      name: w.meta.name,
      shortName: '수원시 통합 오픈월드',
      badgeLabel: spawn.badgeLabel,
      originLat: w.meta.origin.lat,
      originLon: w.meta.origin.lon,
      worldLimit: Math.ceil(Math.max(-b.minX, b.maxX, -b.minZ, b.maxZ)),
      station: spawn.station,
      scooterSpawn: spawn.scooterSpawn,
      playerSpawn: spawn.playerSpawn,
      unified: true,
    },
    nodes: w.nodes,
    edges: w.edges,
    pedestrianPlazas: [],
    buildings: [],
    parks: [],
    waters: [],
    shops: [...districts.flatMap((d) => d.shops), ...(w.generatedShops ?? [])],
    residences: [...districts.flatMap((d) => d.residences), ...(w.generatedResidences ?? [])],
    busStops: w.busStops,
    serviceSpots: spawn.serviceSpots,
    serviceSpotList: districts.map((d) => ({
      districtId: d.id as SuwonDistrictId,
      gas: d.serviceSpots.gas,
      repair: d.serviceSpots.repair,
    })),
    fuelStations: w.generatedFuelStations ?? [],
  };
}

/** District whose hand-tuned area the point is in (or nearest to) — for HUD badges & area names */
export function nearestLegacyDistrictId(x: number, z: number): SuwonDistrictId {
  let best = SUWON_OPEN_WORLD.legacyDistricts[0];
  let bestD = Infinity;
  for (const d of SUWON_OPEN_WORLD.legacyDistricts) {
    const dist = Math.hypot(x - d.origin.x, z - d.origin.z);
    if (dist < bestD) {
      bestD = dist;
      best = d;
    }
  }
  return best.id as SuwonDistrictId;
}
